def find_relevant_rows(table, question):
  relevant_rows = []
  for row in table:
    if any(q in str(row) for q in question):
      relevant_rows.append(row)
  return relevant_rows

def format_answer(relevant_rows, question):
  answers = []
  for q in question:
    if 'over 20 years' in q:
      for row in relevant_rows:
        if row['Duration (Years, Days)'].split(' ')[0] > '20':
          answers.append(row['President'])
    elif 'how long was the 11,611 days?' in q:
      for row in relevant_rows:
        if row['Duration (Days)'] == '11,611 days':
          answers.append(row['Duration (Years, Days)'])
    elif 'greater than 60 years' in q:
      for row in relevant_rows:
        if int(row['Age at Start Date'].split(' ')[0]) > 60:
          answers.append(row['President'])
    elif 'least amount of time' in q:
      min_duration = relevant_rows[0]['Duration (Days)']
      min_duration_president = relevant_rows[0]['President']
      for row in relevant_rows:
        if int(row['Duration (Days)']) < int(min_duration):
          min_duration = row['Duration (Days)']
          min_duration_president = row['President']
      answers.append(min_duration_president)
    elif 'shortest time' in q:
      min_duration = relevant_rows[0]['Duration (Days)']
      min_duration_president = relevant_rows[0]['President']
      for row in relevant_rows:
        if int(row['Duration (Days)']) < int(min_duration):
          min_duration = row['Duration (Days)']
          min_duration_president = row['President']
      answers.append(min_duration_president)
    elif 'less than a year' in q:
      for row in relevant_rows:
        if int(row['Duration (Days)'].split(' ')[0]) < 365:
          answers.append(row['President'])
  return answers

relevant_rows = find_relevant_rows(table, question)
answer = format_answer(relevant_rows, question)
print(f"Evidence: | \n {relevant_rows}")
print(f"Reasoning: | \n The relevant rows are extracted by checking if any word in the question is present in the row. Based on this, the answers to the question are computed using the relevant rows.\n")
print(f"Answer: | \n {answer}")
```

